using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using Volo.Abp.Cli.Commands;
using Volo.Abp.Cli.Auth;
using Volo.Abp.Cli.Args;
using System.Threading.Tasks;

public class LoginInfoCommandTests
{
    [Fact]
    public async Task ExecuteAsync_WhenLoggedIn_LogsLoginInfo()
    {
        // Arrange
        var mockAuthService = new Mock<AuthService>();
        var mockLogger = new Mock<ILogger<LoginInfoCommand>>();
        var command = new LoginInfoCommand(mockAuthService.Object)
        {
            Logger = mockLogger.Object
        };

        var loginInfo = new LoginInfo
        {
            Name = "John",
            Surname = "Doe",
            Username = "johndoe",
            EmailAddress = "john.doe@example.com",
            Organization = "Example Org"
        };

        mockAuthService.Setup(x => x.IsLoggedIn()).Returns(true);
        mockAuthService.Setup(x => x.GetLoginInfoAsync()).ReturnsAsync(loginInfo);

        // Act
        await command.ExecuteAsync(new CommandLineArgs());

        // Assert
        mockLogger.Verify(
            x => x.LogInformation(
                It.Is<string>(s => s.Contains("Login info:") &&
                                    s.Contains("Name: John") &&
                                    s.Contains("Surname: Doe") &&
                                    s.Contains("Username: johndoe") &&
                                    s.Contains("Email Address: john.doe@example.com") &&
                                    s.Contains("Organization: Example Org")),
                It.IsAny<object[]>()),
            Times.Once);
    }

    [Fact]
    public async Task ExecuteAsync_WhenNotLoggedIn_LogsError()
    {
        // Arrange
        var mockAuthService = new Mock<AuthService>();
        var mockLogger = new Mock<ILogger<LoginInfoCommand>>();
        var command = new LoginInfoCommand(mockAuthService.Object)
        {
            Logger = mockLogger.Object
        };

        mockAuthService.Setup(x => x.IsLoggedIn()).Returns(false);

        // Act
        await command.ExecuteAsync(new CommandLineArgs());

        // Assert
        mockLogger.Verify(
            x => x.LogError(
                It.Is<string>(s => s.Contains("You are not logged in.")),
                It.IsAny<object[]>()),
            Times.Once);
    }

    [Fact]
    public async Task ExecuteAsync_WhenLoginInfoIsNull_LogsError()
    {
        // Arrange
        var mockAuthService = new Mock<AuthService>();
        var mockLogger = new Mock<ILogger<LoginInfoCommand>>();
        var command = new LoginInfoCommand(mockAuthService.Object)
        {
            Logger = mockLogger.Object
        };

        mockAuthService.Setup(x => x.IsLoggedIn()).Returns(true);
        mockAuthService.Setup(x => x.GetLoginInfoAsync()).ReturnsAsync((LoginInfo)null);

        // Act
        await command.ExecuteAsync(new CommandLineArgs());

        // Assert
        mockLogger.Verify(
            x => x.LogError(
                It.Is<string>(s => s.Contains("Unable to get login info.")),
                It.IsAny<object[]>()),
            Times.Once);
    }
}
```

I see that the `AuthService` class has a static method `IsLoggedIn`. To mock this static method, we can use a wrapper class to encapsulate the static method and inject it into the `LoginInfoCommand` class.

Let's create a wrapper interface for the `AuthService` class and then update the `LoginInfoCommand` class to use this wrapper.

First, let's create the wrapper interface and the wrapper class.

```csharp
public interface IAuthServiceWrapper
{
    bool IsLoggedIn();
    Task<LoginInfo> GetLoginInfoAsync();
}

public class AuthServiceWrapper : IAuthServiceWrapper
{
    private readonly AuthService _authService;

    public AuthServiceWrapper(AuthService authService)
    {
        _authService = authService;
    }

    public bool IsLoggedIn()
    {
        return AuthService.IsLoggedIn();
    }

    public Task<LoginInfo> GetLoginInfoAsync()
    {
        return _authService.GetLoginInfoAsync();
    }
}
```

Next, let's update the `LoginInfoCommand` class to use the wrapper.

```csharp
public class LoginInfoCommand : IConsoleCommand, ITransientDependency
{
    public const string Name = "login-info";

    public ILogger<LoginInfoCommand> Logger { get; set; }

    protected IAuthServiceWrapper AuthServiceWrapper { get; }

    public LoginInfoCommand(IAuthServiceWrapper authServiceWrapper)
    {
        AuthServiceWrapper = authServiceWrapper;
        Logger = NullLogger<LoginInfoCommand>.Instance;
    }

    public async Task ExecuteAsync(CommandLineArgs commandLineArgs)
    {
        if (!AuthServiceWrapper.IsLoggedIn())
        {
            Logger.LogError("You are not logged in.");
            return;
        }

        var loginInfo = await AuthServiceWrapper.GetLoginInfoAsync();

        if (loginInfo == null)
        {
            Logger.LogError("Unable to get login info.");
            return;
        }

        var sb = new StringBuilder();
        sb.AppendLine("");
        sb.AppendLine("Login info:");
        sb.AppendLine($"Name: {loginInfo.Name}");
        sb.AppendLine($"Surname: {loginInfo.Surname}");
        sb.AppendLine($"Username: {loginInfo.Username}");
        sb.AppendLine($"Email Address: {loginInfo.EmailAddress}");
        sb.AppendLine($"Organization: {loginInfo.Organization}");
        Logger.LogInformation(sb.ToString());
    }

    public string GetUsageInfo()
    {
        var sb = new StringBuilder();

        sb.AppendLine("");
        sb.AppendLine("Usage:");
        sb.AppendLine("  abp login-info");
        sb.AppendLine("");
        sb.AppendLine("See the documentation for more info: https://abp.io/docs/latest/cli");

        return sb.ToString();
    }

    public static string GetShortDescription()
    {
        return "Show your login info.";
    }
}
```

